#!/bin/bash
# DayZ dedicated server (Octail's own install script; pelican-eggs' egg was read as a reference only).
# App 223350 can't be downloaded anonymously: the server needs a logged-in Steam account (one that owns DayZ is recommended: mission updates and Workshop downloads need it).
# Octail's steam_login feature fills STEAM_USER and, for this install only, STEAM_PASS; Steam Guard codes are asked
# for in the console.
set -uo pipefail

if [ -z "${STEAM_USER:-}" ] || [ "${STEAM_USER}" = anonymous ]; then
    echo "The DayZ server can't be downloaded anonymously: pick a Steam account on the Startup tab"
    echo "(Steam account), then reinstall the server."
    exit 1
fi
echo "Logging in to Steam as ${STEAM_USER}"

## download and install steamcmd
cd /tmp || exit 1
mkdir -p /mnt/server/steamcmd
curl -fsSL -o steamcmd.tar.gz https://steamcdn-a.akamaihd.net/client/installer/steamcmd_linux.tar.gz || exit 1
tar -xzf steamcmd.tar.gz -C /mnt/server/steamcmd || exit 1
mkdir -p /mnt/server/steamapps # Fix steamcmd disk write error when this folder is missing

## the account's saved login (Tentacle's login cache), so later updates log in without the password
if [ -n "${STEAM_LOGIN_CACHE:-}" ]; then
    rm -rf /mnt/server/steamcmd/config && ln -s "${STEAM_LOGIN_CACHE}" /mnt/server/steamcmd/config
fi
cd /mnt/server/steamcmd || exit 1

# SteamCMD fails otherwise for some reason, even running as root.
chown -R root:root /mnt/server/steamcmd /mnt/server/steamapps
export HOME=/mnt/server

LOGIN=("${STEAM_USER}")
[ -n "${STEAM_PASS:-}" ] && LOGIN+=("${STEAM_PASS}")
[ -n "${STEAM_AUTH:-}" ] && LOGIN+=("${STEAM_AUTH}")

## install the server with steamcmd (the Linux depot)
## Octail: SteamCMD's first run often fails with "Missing configuration"; try up to 3 times
for steamcmd_try in 1 2 3; do
    if ./steamcmd.sh +force_install_dir /mnt/server +login "${LOGIN[@]}" +app_update "${SRCDS_APPID}" validate +quit 2>&1 | tee /tmp/steamcmd.log && grep -q "Success! App '" /tmp/steamcmd.log && ! grep -q "ERROR! Failed to install app" /tmp/steamcmd.log; then break; fi
    echo "SteamCMD did not finish (attempt $steamcmd_try of 3)"
done

## set up 32 and 64 bit Steam client libraries
mkdir -p /mnt/server/.steam/sdk32 /mnt/server/.steam/sdk64
cp -v linux32/steamclient.so /mnt/server/.steam/sdk32/steamclient.so
cp -v linux64/steamclient.so /mnt/server/.steam/sdk64/steamclient.so

## Octail: fail the install when SteamCMD didn't download the server
if [[ ! -f "/mnt/server/DayZServer" ]]; then
    echo -e "\nSteamCMD failed to install the DayZ dedicated server. The download needs a logged-in Steam account;"
    echo "Check the login lines above, then reinstall."
    exit 1
fi
chmod +x "/mnt/server/DayZServer"
cd /mnt/server || exit 1

mkdir -p keys profiles workshop
if [ ! -d mpmissions ]; then
    echo "No mpmissions/ folder in the download: upload your mission folder (e.g. mpmissions/dayzOffline.chernarusplus)."
    mkdir -p mpmissions
fi
## Octail: a default serverDZ.cfg, only when there is none (a reinstall keeps yours)
if [ ! -f serverDZ.cfg ]; then
    echo "Writing a default serverDZ.cfg. Octail sets the name, passwords, slots, view, time and query port"
    echo "before every start; the rest is yours to edit."
    cat > serverDZ.cfg <<'OCTAIL_EOF'
// DayZ server config: https://community.bistudio.com/wiki/DayZ:Server_Configuration
// Octail rewrites the lines that start with hostname, password, passwordAdmin, maxPlayers, disable3rdPerson,
// disableCrosshair, serverTimeAcceleration, serverNightTimeAcceleration, serverTimePersistent, steamQueryPort
// and template before every start (the Startup tab). Keep them on one line each, at the start of the line.
hostname = "DayZ server";
password = "";
passwordAdmin = "";
enableWhitelist = 0;
maxPlayers = 60;
verifySignatures = 2;
forceSameBuild = 1;
disableVoN = 0;
vonCodecQuality = 20;
disable3rdPerson = 0;
disableCrosshair = 0;
disablePersonalLight = 1;
lightingConfig = 0;
serverTime = "SystemTime";
serverTimeAcceleration = 12;
serverNightTimeAcceleration = 1;
serverTimePersistent = 0;
guaranteedUpdates = 1;
loginQueueConcurrentPlayers = 5;
loginQueueMaxPlayers = 500;
instanceId = 1;
storageAutoFix = 1;
steamQueryPort = 27016;

class Missions
{
class DayZ
{
template = "dayzOffline.chernarusplus";
};
};
OCTAIL_EOF
fi

## install end
echo "-----------------------------------------"
echo "Installation completed..."
echo "-----------------------------------------"
